if tz is not None:
    tz = groups[tz]
if tz == 'Z':
    tz = FixedTzOffset(0, 'UTC')
elif tz:
    tz = tz.strip()
    if tz.isupper():
        # TODO use the awesome python TZ module?
        pass
    else:
        sign = tz[0]
        if ':' in tz:
            tzh, tzm = tz[1:].split(':')
        elif len(tz) <= 3:  # Handle short formats like '+5', '+53'
            # For '+N' treat as hours, for '+NN' treat as hours
            tzh = tz[1:]
            tzm = '0'
        elif len(tz) == 4:  # 'snnn' -> s + hour + minutes(e.g., '+053' = 0h 53m)
            tzh, tzm = tz[1], tz[2:4]
        else:  # 'sHHMM' or longer - standard format
            tzh, tzm = tz[1:3], tz[3:5]
        offset = int(tzm) + int(tzh) * 60
        if sign == '-':
            offset = -offset
        tz = FixedTzOffset(offset, tz)

